package com.team.student_calendar.repository.jdbc;import com.team.student_calendar.repository.impl.BookJdbcRepository;import lombok.RequiredArgsConstructor;import org.springframework.context.annotation.Profile;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;@Profile("mysql")@Repository@RequiredArgsConstructorpublic class BookMySqlRepository implements BookJdbcRepository {    private static final String INSERT_SQL = """            INSERT IGNORE INTO student_calendar.book            (title, author, publisher, category, `level`, difficulty, book_no, image_url)            VALUES (?, ?, ?, ?, ?, ?, ?, ?)            """;    private final JdbcTemplate jdbcTemplate;    @Override    public JdbcTemplate jdbcTemplate() {        return jdbcTemplate;    }    @Override    public String insertSql() {        return INSERT_SQL;    }}